3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailConflictException;
10	
11	/**
12	 * Rejects a create-owner request whose lower-cased email is already used by any other owner.
13	 * The email was normalized (trimmed and lower-cased) by {@link ValidateOwnerFields} and published on
14	 * the body; this step compares that value against the lower-cased email of every existing owner and
15	 * throws {@link OwnerEmailConflictException} (handled as 409) on a match. An absent email never
16	 * conflicts.
17	 */
18	public class CheckOwnerEmailUnique {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws OwnerEmailConflictException {
22	        String email = request.getEmail();
23	        if (email == null) {
24	            return;
25	        }
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (email.equals(normalize(existing.getEmail()))) {
28	                throw new OwnerEmailConflictException(request.getEmail());
29	            }
30	        }
31	    }
32	
33	    private static String normalize(String email) {
34	        if (email == null || email.isBlank()) {
35	            return null;
36	        }
37	        return email.trim().toLowerCase(Locale.ROOT);
38	    }
39	}
