3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneConflictException;
8	
9	/**
10	 * Rejects a create-owner request whose telephone is already used by any other owner.
11	 * The telephone was normalized to E.164 form by {@link ValidateOwnerFields} and published on the
12	 * body; this step compares that E.164 value against the E.164 form of every existing owner's
13	 * telephone and throws {@link OwnerTelephoneConflictException} (handled as 409) on a match.
14	 */
15	public class CheckOwnerTelephoneUnique {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws OwnerTelephoneConflictException {
19	        String telephone = normalize(request.getTelephone());
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone != null && telephone.equals(normalize(existing.getTelephone()))) {
22	                throw new OwnerTelephoneConflictException(request.getTelephone());
23	            }
24	        }
25	    }
26	
27	    /** Best-effort E.164 form for comparison; falls back to the raw value when unparseable. */
28	    private static String normalize(String telephone) {
29	        try {
30	            return OwnerTelephone.toE164(telephone);
31	        }
32	        catch (Exception ex) {
33	            return telephone;
34	        }
35	    }
36	}
