1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerHouseholdConflictException;
8	
9	/**
10	 * Rejects a create-owner request that would share a household with an existing owner — the same
11	 * lastName (compared case-insensitively with collapsed whitespace) and the same address, compared
12	 * in normalized form (see {@link OwnerAddress#normalize(String)}). Throws
13	 * {@link OwnerHouseholdConflictException} (handled as 409) on a match, unless the request opted in
14	 * with {@code sharesHousehold: true}, in which case the duplicate is allowed.
15	 */
16	public class CheckOwnerHouseholdUnique {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws OwnerHouseholdConflictException {
20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        String lastName = normalize(request.getLastName());
24	        String address = OwnerAddress.forComparison(request.getAddress());
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (lastName.equals(normalize(existing.getLastName()))
27	                    && address.equals(OwnerAddress.forComparison(existing.getAddress()))) {
28	                throw new OwnerHouseholdConflictException(request.getLastName(), request.getAddress());
29	            }
30	        }
31	    }
32	
33	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
34	    private static String normalize(String value) {
35	        if (value == null) {
36	            return "";
37	        }
38	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
39	    }
40	}
