33	            return;
34	        }
35	        String lastName = normalize(owner.getLastName());
36	        String address = OwnerAddress.forComparison(owner.getAddress());
37	        List<Owner> household = new ArrayList<>();
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (lastName.equals(normalize(existing.getLastName()))
40	                    && address.equals(OwnerAddress.forComparison(existing.getAddress()))) {
41	                household.add(existing);
42	            }
43	        }
44	        if (household.isEmpty()) {
45	            return;
46	        }
47	        String householdId = deriveHouseholdId(lastName, address);
48	        owner.setHouseholdId(householdId);
49	        for (Owner existing : household) {
50	            if (!householdId.equals(existing.getHouseholdId())) {
51	                existing.setHouseholdId(householdId);
52	                ownerRepository.save(existing);
53	            }
54	        }
55	    }
56	
57	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
58	    private static String normalize(String value) {
59	        if (value == null) {
60	            return "";
61	        }
62	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
