66	     *  computed over the already-normalized values so it is identical for every household member. */
67	    private static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
68	        try {
69	            byte[] digest = MessageDigest.getInstance("SHA-256")
70	                    .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
71	            StringBuilder sb = new StringBuilder();
72	            for (int i = 0; i < 6; i++) {
73	                sb.append(String.format("%02X", digest[i]));
74	            }
75	            return "HH-" + sb;
76	        }
77	        catch (Exception ex) {
78	            throw new IllegalStateException("SHA-256 unavailable", ex);
79	        }
80	    }
