12	
13	/**
14	 * First step of {@code POST /api/owners}. Rejects a request that is missing or blank in any of
15	 * firstName, lastName, address, city or telephone, collecting every offending field name so the
16	 * response can list them all. The address is normalized first (see
17	 * {@link OwnerAddress#normalize(String)}) and rejected when it is blank after normalization. It then
18	 * normalizes the telephone into E.164 form (see {@link OwnerTelephone#toE164(String)}), storing the
19	 * normalized address and telephone back on the body so they are persisted and
20	 * returned. On success it publishes the body for {@link BuildOwner} to consume
21	 * (only one step may bind {@code @RequestBody}).
22	 */
23	public class ValidateOwnerFields {
24	
25	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
26	            throws OwnerFieldsRequiredException, OwnerTelephoneInvalidException, OwnerEmailInvalidException {
27	        List<String> errors = new ArrayList<>();
28	        require("firstName", request.getFirstName(), errors);
29	        require("lastName", request.getLastName(), errors);
30	        // Normalize the address up front so the required check rejects one that is blank after
31	        // normalization, and the normalized value is what gets stored and returned.
32	        String normalizedAddress = OwnerAddress.normalize(request.getAddress());
33	        if (normalizedAddress == null) {
34	            errors.add("address");
35	        }
36	        require("city", request.getCity(), errors);
37	        require("telephone", request.getTelephone(), errors);
38	        if (!errors.isEmpty()) {
39	            throw new OwnerFieldsRequiredException(errors);
40	        }
41	        request.setAddress(normalizedAddress);
42	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
43	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
44	        validated.set(request);
45	    }
46	
47	    private static void require(String field, String value, List<String> errors) {
48	        if (value == null || value.isBlank()) {
49	            errors.add(field);
50	        }
51	    }
52	}
