3	import java.util.Locale;
4	
5	/**
6	 * Shared address handling for owner endpoints. An owner's address is stored, returned and compared
7	 * in a canonical form: trimmed with internal whitespace runs collapsed to a single space,
8	 * upper-cased, and with the common street-type abbreviations expanded — {@code ST -> STREET},
9	 * {@code RD -> ROAD}, {@code AVE -> AVENUE} (whole tokens only). So {@code '  12  main  st '}
10	 * becomes {@code '12 MAIN STREET'}.
11	 */
12	final class OwnerAddress {
13	
14	    private OwnerAddress() {
15	    }
16	
17	    /**
18	     * Returns the normalized address, or {@code null} when the input is null or blank after
19	     * trimming and collapsing whitespace — so a required-field check can reject it.
20	     */
21	    static String normalize(String address) {
22	        if (address == null) {
23	            return null;
24	        }
25	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
26	        if (collapsed.isEmpty()) {
27	            return null;
28	        }
29	        String[] tokens = collapsed.split(" ");
30	        StringBuilder sb = new StringBuilder(collapsed.length());
31	        for (int i = 0; i < tokens.length; i++) {
32	            if (i > 0) {
33	                sb.append(' ');
34	            }
35	            sb.append(expand(tokens[i]));
36	        }
37	        return sb.toString();
38	    }
39	
40	    /**
41	     * Normalized address for comparison, never {@code null}: a null or blank address collapses to
42	     * the empty string so two addressless owners compare equal.
43	     */
44	    static String forComparison(String address) {
45	        String normalized = normalize(address);
46	        return normalized == null ? "" : normalized;
47	    }
48	
49	    private static String expand(String token) {
50	        switch (token) {
51	            case "ST":
52	                return "STREET";
53	            case "RD":
54	                return "ROAD";
55	            case "AVE":
56	                return "AVENUE";
57	            default:
58	                return token;
59	        }
60	    }
61	}
